using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DicesRewardsList", menuName = "Data/Battle/Dice System/Dices Rewards List")]
public class DicesRewardsList : ScriptableObject
{
	[Header("Character")]
	[SerializeField]
	private bool runtimeNoSpecificCharacter;

	[SerializeField]
	[HideIf("runtimeNoSpecificCharacter")]
	private Character character;

	[Header("Lists")]
	[SerializeField]
	private DiceTierDiceList[] diceTierDiceLists;

	[Header("Mods")]
	[SerializeField]
	private DiceTierDiceList[] diceTierDiceListsMods;

	public Character Character => character;

	public DiceTierDiceList[] DiceTierDiceLists => diceTierDiceLists;

	public DiceTierDiceList[] DiceTierDiceListsMods => diceTierDiceListsMods;

	public DiceTierDiceList GetDiceTierDiceList(DiceTier diceTier)
	{
		for (int i = 0; i < diceTierDiceLists.Length; i++)
		{
			if (diceTierDiceLists[i].tier == diceTier)
			{
				return diceTierDiceLists[i];
			}
		}
		return null;
	}

	public List<Dice> GetAllDice(bool getDiceMod = false)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < diceTierDiceLists.Length; i++)
		{
			list.AddRange(diceTierDiceLists[i].diceList);
		}
		if (getDiceMod)
		{
			for (int j = 0; j < diceTierDiceListsMods.Length; j++)
			{
				list.AddRange(diceTierDiceListsMods[j].diceList);
			}
		}
		return list;
	}

	public List<Dice> GetAllDiceButTier(DiceTier diceTier)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < diceTierDiceLists.Length; i++)
		{
			if (diceTierDiceLists[i].tier != diceTier)
			{
				list.AddRange(diceTierDiceLists[i].diceList);
			}
		}
		return list;
	}

	public void PopulateDiceTierDiceListsMods(List<PlayerDice> diceMods)
	{
		for (int num = diceMods.Count - 1; num >= 0; num--)
		{
			PlayerDice playerDice = diceMods[num];
			if (playerDice.Character == character)
			{
				GetDiceTierDiceListMods(playerDice.DiceTier).diceList.Add(playerDice);
				diceMods.Remove(playerDice);
			}
		}
	}

	private DiceTierDiceList GetDiceTierDiceListMods(DiceTier diceTier)
	{
		for (int i = 0; i < diceTierDiceListsMods.Length; i++)
		{
			if (diceTierDiceListsMods[i].tier == diceTier)
			{
				return diceTierDiceListsMods[i];
			}
		}
		return null;
	}

	public void ClearDiceTierDiceListsMods(DiceTier[] diceTiers)
	{
		if (diceTierDiceListsMods.Length != diceTiers.Length)
		{
			diceTierDiceListsMods = new DiceTierDiceList[diceTiers.Length];
			for (int i = 0; i < diceTierDiceListsMods.Length; i++)
			{
				diceTierDiceListsMods[i] = new DiceTierDiceList(diceTiers[i]);
			}
		}
		for (int j = 0; j < diceTierDiceListsMods.Length; j++)
		{
			diceTierDiceListsMods[j].diceList.Clear();
		}
	}
}
